import{z as s,x as i,o as B,c as n,q as e,j as t,D as a,d as o,s as l,S as r}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"SLO 分层与差异化","description":"","frontmatter":{"title":"SLO 分层与差异化","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/sch-slo-tiers.md","filePath":"llm/sch-slo-tiers.md","lastUpdated":1791063341000}'),d={name:"llm/sch-slo-tiers.md"};function p(C,E,T,D,h,S){const A=i("Mermaid");return B(),n("div",null,[E[2]||(E[2]=e('<h1 id="slo-分层与差异化" tabindex="-1">SLO 分层与差异化 <a class="header-anchor" href="#slo-分层与差异化" aria-label="Permalink to &quot;SLO 分层与差异化&quot;">​</a></h1><div class="epigraph"><p>一刀切的 SLO 实际是最严那档的全员税；分层不是给流量贴标签，是把不可同时满足的承诺拆到各自可满足的池子里。</p><footer>—— 据 Zhong et al., OSDI 2024（goodput 口径）与 Liu 与 Layland, 1973（截止期调度）整理</footer></div><p><a href="/llm/sch-priority-fairness">上一课</a>给了类别与权重这套策略机制；本课把类别升格为合同：每层写明 TTFT 与 TPOT 的分位承诺、资源份额与超卖比例，并给每层配不同的调度机制。SLO 的写法与尾延迟的来源主干已有（<a href="/llm/serving-slo">服务 SLO 与尾延迟</a>、<a href="/llm/priority-sla">优先级与 SLA</a>），本课只写分层之后调度器具体做什么。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>全系统一个 SLO，等于用最严的档约束所有流量：<span class="marginnote">术语翻译：SLO 是服务给自己定的目标（如「P99 TTFT \\(\\lt\\) 800 ms」），写进合同、违了要赔的就是 SLA。P99 指「100 个请求里最慢的那一个也不能超过这条线」——尾部被写进数字，才算真的被管住。</span>交互聊天的 TTFT 承诺逼着离线摘要也走小批快步，批处理本可以填满的算力空隙被互动流的保护策略占着；反过来用最松的档，交互流的尾巴违约。根因是不同承诺在同一配置下本就不可同时满足。DistServe 的出发点正在于此：colocate 系统无法同时优化 TTFT 与 TPOT 两个 SLO，于是把目标改写成 goodput——满足双 SLO 的请求速率最大化（Zhong et al., OSDI 2024）。分层把这个思想从「两阶段」推广到「多类流量」：每一层是一组可满足的承诺，goodput 把各层合成一个总目标。</p><h3 id="层的定义与机制匹配" tabindex="-1">层的定义与机制匹配 <a class="header-anchor" href="#层的定义与机制匹配" aria-label="Permalink to &quot;层的定义与机制匹配&quot;">​</a></h3><p>每层三件套：<strong>承诺</strong>（P99 TTFT、P99 TPOT）、<strong>份额</strong>（token 预算与并发上限）、<strong>超卖比例</strong>（允许多少倍共用）。机制按承诺配：交互层预算紧、prefill 块小、准入严格；批处理层批大、可被抢占、填谷时跑；agent 层 TPOT 敏感、decode 亲和固定实例（<a href="/llm/decode-affinity">Decode 实例的亲和与缓存</a>）。层内排序用截止期：按「承诺还剩多少时间」排而不是按到达排——EDF 在单机上的最优性是硬实时调度的老结论（Liu 与 Layland, 1973），搬到这里只取方向：LLM 的服务时间方差极大，截止期排序的预算仍要按分位留。准入按层独立：每层自己的令牌桶与运行上限，跨层不许透支——低层的满载不能吃掉高层的水位。</p>',7)),(B(),t(r,null,{default:a(()=>[l(A,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20REQ%5B%22%E8%AF%B7%E6%B1%82%E5%88%B0%E8%BE%BE%EF%BC%9A%E5%B8%A6%E5%B1%82%E6%A0%87%22%5D%20--%3E%20CLS%7B%22%E5%B1%82%E5%88%A4%E5%AE%9A%EF%BC%9AAPI%20%E4%B8%8E%E5%90%88%E5%90%8C%22%7D%0A%20%20CLS%20--%3E%7C%E4%BA%A4%E4%BA%92%7C%20T1%5B%22%E4%BA%A4%E4%BA%92%E5%B1%82%EF%BC%9A%E7%B4%A7%E9%A2%84%E7%AE%97%EF%BC%8C%E4%B8%A5%E6%A0%BC%E5%87%86%E5%85%A5%22%5D%0A%20%20CLS%20--%3E%7CAgent%7C%20T2%5B%22Agent%20%E5%B1%82%EF%BC%9ATPOT%20%E4%BC%98%E5%85%88%EF%BC%8C%E5%9B%BA%E5%AE%9A%E4%BA%B2%E5%92%8C%22%5D%0A%20%20CLS%20--%3E%7C%E6%89%B9%E5%A4%84%E7%90%86%7C%20T3%5B%22%E6%89%B9%E5%A4%84%E7%90%86%E5%B1%82%EF%BC%9A%E5%A4%A7%E6%89%B9%EF%BC%8C%E5%8F%AF%E6%8A%A2%E5%8D%A0%EF%BC%8C%E5%A1%AB%E8%B0%B7%22%5D%0A%20%20T1%20--%3E%20LED%5B%22goodput%20%E8%B4%A6%E6%9C%AC%EF%BC%9A%E5%88%86%E5%B1%82%E8%AE%B0%E8%BE%BE%E6%A0%87%E7%8E%87%22%5D%0A%20%20T2%20--%3E%20LED%0A%20%20T3%20--%3E%20LED%0A%20%20LED%20--%3E%20ADJ%5B%22%E4%BB%BD%E9%A2%9D%E4%B8%8E%E8%B6%85%E5%8D%96%E6%8C%89%E8%BF%9D%E7%BA%A6%E8%B0%83%E6%95%B4%22%5D%0A%20%20ADJ%20--%3E%20T1%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[o(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>本课的方法是<strong>目标改写加分池</strong>：先把「同时满足所有承诺」这个不可行目标改写成 goodput——各层承诺内速率之和，取 DistServe 的口径从两阶段推广到多类流量；再给每层配三件套（承诺、份额、超卖比例），机制按承诺逐层配，不共用一套旋钮。层内排序取 EDF 的方向，层间准入各自独立。选型理由就写在问题里：不可同时满足的约束，工程上只剩拆开分别满足一条路。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>分层为什么有效：它把混合的尾巴拆成可分别工程化的对象。<span class="marginnote">直觉类比：一刀切的 SLO 像要求整栋楼统一保持图书馆级别的安静——所有住户都被最严的标准管着；分层则是每个房间自己定规矩，客厅可以热闹、书房必须安静，整栋楼反而各得其所。</span>交互层的违约原因几乎总是 prefill 插队与准入失控；批处理层的违约原因是被抢占过多；agent 层是亲和被打破。原因不同，药不同——混在一条队列里，三种原因互相掩盖。层的成本是预留：份额给出去就不能同时在别处兑现，超卖比例就是这层的定价；超卖依据是各类流量的峰值不同相（白天交互、夜里批处理），但相关性在事故里会变 1，预留要按最坏相关做测试。验收逐层做对抗：批处理层打满时，交互层的分位不动才算分层成功。</p><p>超卖之所以敢存在，靠的是峰值不同相：</p>',5)),(B(),t(r,null,{default:a(()=>[l(A,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20DAY%5B%22%E7%99%BD%E5%A4%A9%EF%BC%9A%E4%BA%A4%E4%BA%92%E6%B5%81%E5%B3%B0%E5%80%BC%22%5D%0A%20%20%20%20D1%5B%22%E4%BA%A4%E4%BA%92%E5%B1%82%E4%BB%BD%E9%A2%9D%E6%8B%89%E6%BB%A1%22%5D%20--%3E%20D2%5B%22%E6%89%B9%E5%A4%84%E7%90%86%E5%B1%82%E8%AE%A9%E8%B7%AF%EF%BC%8C%E5%8F%AA%E5%9C%A8%E8%B0%B7%E9%87%8C%E8%B7%91%22%5D%0A%20%20end%0A%20%20subgraph%20NIGHT%5B%22%E5%A4%9C%E9%87%8C%EF%BC%9A%E6%89%B9%E6%B5%81%E5%B3%B0%E5%80%BC%22%5D%0A%20%20%20%20N1%5B%22%E4%BA%A4%E4%BA%92%E6%B5%81%E9%87%8F%E8%90%BD%E8%B0%B7%22%5D%20--%3E%20N2%5B%22%E6%89%B9%E5%A4%84%E7%90%86%E5%B1%82%E5%90%83%E4%B8%8B%E7%A9%BA%E5%87%BA%E7%9A%84%E7%AE%97%E5%8A%9B%22%5D%0A%20%20end%0A%20%20DAY%20--%3E%7C%22%E5%B3%B0%E5%80%BC%E9%94%99%E5%BC%80%EF%BC%8C%E5%90%8C%E4%B8%80%E6%89%B9%E5%8D%A1%E5%8F%AF%E6%8C%89%E6%AF%94%E4%BE%8B%E8%B6%85%E5%8D%96%22%7C%20NIGHT%0A%20%20NIGHT%20--%3E%7C%22%E4%BA%8B%E6%95%85%E6%97%B6%E7%9B%B8%E5%85%B3%E6%80%A7%E5%8F%98%201%22%7C%20RISK%5B%22%E9%A2%84%E7%95%99%E4%B8%8E%E6%B5%8B%E8%AF%95%E6%8C%89%E6%9C%80%E5%9D%8F%E7%9B%B8%E5%85%B3%E5%81%9A%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[o(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=e('<p><span class="marginnote">goodput 是分层的合成指标：各层各报一个「承诺内速率」，总 goodput 是它们之和。DistServe 用它证明分开优化值得：同等硬件下 goodput 提升约 7.4 倍，SLO 更紧时约 12.6 倍——数字随负载变，方向不变：不可同时满足的承诺，必须分池。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>层不是越多越好：每层要足够的流量才能验证分位数，五层以上多数服务养不起统计，方差小的层该并。<span class="marginnote">常见误区：初学者容易把「层」当荣誉称号，越分越细。每层的 P99 都要有足够样本才统计得稳——流量稀的层，分位数本身就是噪声，调参等于对噪声做优化。多数服务两三层足够，第五层起通常养不起。</span>层间迁移（用户升级套餐、重试换层）要显式定义，不能靠重试穿透配额。退款与赔付是商务条款，超出调度器管辖，但合同的数字必须来自调度器能测的那本账（<a href="/llm/priority-sla">优先级与 SLA</a>）。分层也不替代容量：全部层同时超载时，剩下的是运维单元的过载与伸缩问题。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>一刀切 SLO 是最严档的全员税；分层把不可同时满足的承诺拆开。</li><li>层 = 承诺（双分位）+ 份额 + 超卖比例；机制按承诺配，不共用一套旋钮。</li><li>层内按截止期排序（取 EDF 方向），层间准入独立、不许透支。</li><li>goodput 分层记账，是分层的合成目标函数。</li><li>层的定价是超卖比例；验收必须逐层做对抗测试。</li><li>出处：Zhong et al., OSDI 2024（goodput）；Liu 与 Layland, JACM 1973（EDF）；分位合同写法见站内 SLO 专文。</li></ul>',5))])}const _=s(d,[["render",p]]);export{u as __pageData,_ as default};
